const fs = require('fs');
const zlib = require('zlib');

// Read the docx file as a buffer and parse the ZIP manually
const buf = fs.readFileSync('customer_report.docx');

// ZIP files: find local file headers and locate word/document.xml
// ZIP end of central directory is at the end
// Let's find 'word/document.xml' in the buffer
const filename = 'word/document.xml';
const fnBuf = Buffer.from(filename);

// Search for the central directory entry for word/document.xml
let idx = buf.indexOf(fnBuf);
while (idx !== -1) {
    // Check if this is a local file header (PK\\x03\\x04) before the filename
    // Local file header: offset - 30 (fixed header size) but filename length varies
    // Let's look backwards for PK signature
    let headerStart = -1;
    for (let i = idx - 1; i >= Math.max(0, idx - 100); i--) {
        if (buf[i] === 0x50 && buf[i+1] === 0x4B && buf[i+2] === 0x03 && buf[i+3] === 0x04) {
            headerStart = i;
            break;
        }
    }

    if (headerStart !== -1) {
        // Parse local file header
        const compressionMethod = buf.readUInt16LE(headerStart + 8);
        const compressedSize = buf.readUInt32LE(headerStart + 18);
        const uncompressedSize = buf.readUInt32LE(headerStart + 22);
        const fnLength = buf.readUInt16LE(headerStart + 26);
        const extraLength = buf.readUInt16LE(headerStart + 28);
        const dataStart = headerStart + 30 + fnLength + extraLength;

        let content;
        if (compressionMethod === 0) {
            content = buf.slice(dataStart, dataStart + uncompressedSize).toString('utf8');
        } else {
            // Deflate
            const compressed = buf.slice(dataStart, dataStart + compressedSize);
            content = zlib.inflateRawSync(compressed).toString('utf8');
        }

        // Parse XML to extract text
        const paragraphs = [];
        const paraRegex = /<w:p[ >][\s\S]*?<\/w:p>/g;
        let m;
        while ((m = paraRegex.exec(content)) !== null) {
            const paraXml = m[0];
            const texts = [];
            const tRegex = /<w:t[^>]*>([^<]*)<\/w:t>/g;
            let t;
            while ((t = tRegex.exec(paraXml)) !== null) {
                texts.push(t[1]);
            }
            if (texts.length > 0) {
                paragraphs.push(texts.join(''));
            }
        }
        console.log(paragraphs.join('\n\n'));
        break;
    }

    idx = buf.indexOf(fnBuf, idx + 1);
}
